// Quizzone - team device
// Generated by firmware/tools/build.mjs - edit firmware/src instead.

// ===== qz_config.ts =====
// =============================================================================
//  Quizzone - shared settings. Must be IDENTICAL on every team device
//  and on the base station (the micro:bit plugged into the computer).
// =============================================================================

// --- Radio network ----------------------------------------------------------
// The micro:bit radio frequency is 2400 MHz + band (MHz). MakeCode's default
// band is 7 (2407 MHz), which sits on top of Wi-Fi channel 1: avoid it.
// Verified in the codal/pxt source: group 0..255, band 0..83, power 0..7.
// Pick a group/band that no other micro:bit activity in the venue uses.
const QZ_GROUP = 77;
const QZ_BAND = 25;
const QZ_TX_POWER = 7;

// Firmware / protocol version reported by team devices (uint8).
const QZ_FW = 1;

// Maximum number of teams (the ack/result masks are 16 bits wide).
const QZ_MAX_TEAMS = 16;

// --- Timing (milliseconds) --------------------------------------------------
const QZ_BEACON_MS = 100;        // base -> teams state beacon period
const QZ_SERVER_TIMEOUT_MS = 3000; // base: no valid state line from the PC -> OFFLINE
const QZ_BASE_HELLO_MS = 2000;   // base -> PC "H" heartbeat line period
const QZ_STALE_MS = 1500;        // team: ignore key presses if last beacon is older
const QZ_NOLINK_MS = 2500;       // team: show "no link" if no beacon for this long
const QZ_DEBOUNCE_MS = 10;       // key must be stable this long to count
const QZ_HB_MS = 1000;           // team: idle heartbeat (state) period, +0..300 jitter
const QZ_UNASSIGNED_HB_MS = 600; // team without a slot announces itself this often (+0..400)
const QZ_RXQ_MAX = 64;           // base: software queue between radio and serial

// ===== qz_protocol.ts =====
// =============================================================================
//  Quizzone - wire protocol (radio packets + serial lines).
//  Spec: protocol/PROTOCOL.md.  Pure functions only: no MakeCode API here, so
//  the same file runs in the Node test harness.
//  MakeCode static-TS rules followed: no enums, no namespaces, no modules.
// =============================================================================

const QZ_MAGIC = 0xC5;

const QZ_T_STATE = 1;    // team  -> base
const QZ_T_BEACON = 2;   // base  -> teams
const QZ_T_ASSIGN = 3;   // base  -> one team (by serial)
const QZ_T_IDENT = 4;    // base  -> one team (by serial)

const QZ_STATE_LEN = 13;
const QZ_BEACON_LEN = 16;
const QZ_ASSIGN_LEN = 7;
const QZ_IDENT_LEN = 7;

// Phases carried in beacons.
const QZ_PH_IDLE = 0;
const QZ_PH_OPEN = 1;
const QZ_PH_CLOSED = 2;
const QZ_PH_REVEAL = 3;
const QZ_PH_OFFLINE = 4;   // generated by the base when the PC went silent

const QZ_UNASSIGNED = 255;

// STATE.flags bits
const QZ_SF_LOCKED = 1;        // bit0: device holds an answer for state.q
const QZ_SF_ACKED = 2;         // bit1: device has seen the base acknowledge it
const QZ_SF_PHASE_SHIFT = 2;   // bits2-4: phase of the last beacon the device processed
const QZ_SF_TEST = 32;         // bit5: last beacon had test flag

// BEACON.flags bits
const QZ_BF_TEST = 1;          // bit0: stress-test mode (devices auto-answer)
const QZ_BF_NANS_SHIFT = 2;    // bits2-4: number of valid answers (3..5)

class QzMsg {
    type = 0;
    // STATE fields
    slot = 0;
    seq = 0;
    q = 0;
    ans = 0;
    elapsed = 0;
    flags = 0;
    fw = 0;
    presses = 0;
    bmiss = 0;
    // BEACON fields (q, elapsed, flags are shared with STATE)
    phase = 0;
    limit = 0;      // units of 100 ms
    ack = 0;
    correct = 0;
    wrong = 0;
    bseq = 0;
    // ASSIGN / IDENT
    target = 0;     // device serial number as int32
    arg = 0;        // slot (ASSIGN) or pattern (IDENT)
    constructor() { }
}

function qzClamp16(v: number): number {
    if (v < 0) return 0;
    if (v > 65535) return 65535;
    return v;
}

function qzEncState(m: QzMsg): number[] {
    const e = qzClamp16(m.elapsed);
    return [QZ_MAGIC, QZ_T_STATE, m.slot & 255, m.seq & 255, m.q & 255, m.ans & 255,
        e & 255, (e >> 8) & 255, m.flags & 255, m.fw & 255,
        m.presses & 255, (m.presses >> 8) & 255, m.bmiss & 255];
}

function qzEncBeacon(m: QzMsg): number[] {
    const e = qzClamp16(m.elapsed);
    const l = qzClamp16(m.limit);
    return [QZ_MAGIC, QZ_T_BEACON, m.phase & 255, m.q & 255,
        e & 255, (e >> 8) & 255, l & 255, (l >> 8) & 255,
        m.ack & 255, (m.ack >> 8) & 255,
        m.correct & 255, (m.correct >> 8) & 255,
        m.wrong & 255, (m.wrong >> 8) & 255,
        m.flags & 255, m.bseq & 255];
}

function qzEncTargeted(type: number, target: number, arg: number): number[] {
    return [QZ_MAGIC, type, target & 255, (target >> 8) & 255, (target >> 16) & 255,
        (target >> 24) & 255, arg & 255];
}

// Returns null for anything that is not a well-formed Quizzone packet.
function qzDecode(b: number[]): QzMsg {
    if (b == null || b.length < 2 || b[0] != QZ_MAGIC) return null;
    const m = new QzMsg();
    m.type = b[1];
    if (m.type == QZ_T_STATE) {
        if (b.length != QZ_STATE_LEN) return null;
        m.slot = b[2]; m.seq = b[3]; m.q = b[4]; m.ans = b[5];
        m.elapsed = b[6] | (b[7] << 8);
        m.flags = b[8]; m.fw = b[9];
        m.presses = b[10] | (b[11] << 8);
        m.bmiss = b[12];
        return m;
    }
    if (m.type == QZ_T_BEACON) {
        if (b.length != QZ_BEACON_LEN) return null;
        m.phase = b[2]; m.q = b[3];
        m.elapsed = b[4] | (b[5] << 8);
        m.limit = b[6] | (b[7] << 8);
        m.ack = b[8] | (b[9] << 8);
        m.correct = b[10] | (b[11] << 8);
        m.wrong = b[12] | (b[13] << 8);
        m.flags = b[14]; m.bseq = b[15];
        return m;
    }
    if (m.type == QZ_T_ASSIGN || m.type == QZ_T_IDENT) {
        if (b.length != QZ_ASSIGN_LEN) return null;
        m.target = b[2] | (b[3] << 8) | (b[4] << 16) | (b[5] << 24);
        m.arg = b[6];
        return m;
    }
    return null;
}

// ---------------------------------------------------------------------------
//  Serial lines:  "<payload>*<HH>"  where HH = XOR of all payload bytes, hex.
// ---------------------------------------------------------------------------

function qzChecksum(s: string): number {
    let c = 0;
    for (let i = 0; i < s.length; i++) c ^= s.charCodeAt(i);
    return c & 255;
}

function qzHexDigit(v: number): string {
    return "0123456789ABCDEF".charAt(v & 15);
}

function qzHex2(v: number): string {
    return qzHexDigit(v >> 4) + qzHexDigit(v);
}

// Unsigned 8-digit hex of an int32.
function qzHex8(v: number): string {
    let s = "";
    for (let i = 7; i >= 0; i--) s += qzHexDigit((v >> (i * 4)) & 15);
    return s;
}

function qzAddChecksum(payload: string): string {
    return payload + "*" + qzHex2(qzChecksum(payload));
}

// Returns the payload if the line is well-formed and the checksum matches,
// otherwise null. Trailing CR/LF/spaces are ignored.
function qzStripLine(line: string): string {
    let end = line.length;
    while (end > 0) {
        const c = line.charCodeAt(end - 1);
        if (c == 10 || c == 13 || c == 32) end--; else break;
    }
    if (end < 4) return null;
    if (line.charAt(end - 3) != "*") return null;
    const payload = line.substr(0, end - 3);
    const hh = qzParseHex(line.substr(end - 2, 2));
    if (hh < 0) return null;
    if (qzChecksum(payload) != hh) return null;
    return payload;
}

// Parses hex digits into an int32 (wraps like unsigned). Returns -1 on a bad char
// or empty string; callers that need all 32 bits must use qzParseHex32.
function qzParseHex(s: string): number {
    if (s.length == 0 || s.length > 7) return -1;
    let v = 0;
    for (let i = 0; i < s.length; i++) {
        const d = qzHexVal(s.charCodeAt(i));
        if (d < 0) return -1;
        v = (v << 4) | d;
    }
    return v;
}

function qzHexVal(c: number): number {
    if (c >= 48 && c <= 57) return c - 48;
    if (c >= 65 && c <= 70) return c - 55;
    if (c >= 97 && c <= 102) return c - 87;
    return -1;
}

// 8 hex digits -> int32. Sets ok[0] = false on error.
function qzParseHex32(s: string, ok: boolean[]): number {
    if (s.length != 8) { ok[0] = false; return 0; }
    let v = 0;
    for (let i = 0; i < 8; i++) {
        const d = qzHexVal(s.charCodeAt(i));
        if (d < 0) { ok[0] = false; return 0; }
        v = (v << 4) | d;
    }
    return v;
}

// Decimal integer with optional leading '-'. Sets ok[0] = false on error.
function qzParseInt(s: string, ok: boolean[]): number {
    if (s.length == 0 || s.length > 9) { ok[0] = false; return 0; }
    let i = 0;
    let neg = false;
    if (s.charAt(0) == "-") { neg = true; i = 1; if (s.length == 1) { ok[0] = false; return 0; } }
    let v = 0;
    for (; i < s.length; i++) {
        const c = s.charCodeAt(i);
        if (c < 48 || c > 57) { ok[0] = false; return 0; }
        v = v * 10 + (c - 48);
    }
    return neg ? -v : v;
}

// ===== qz_team.ts =====
// =============================================================================
//  Team device logic (runs on each team's micro:bit).
//  Hardware-free: everything goes through QzTeamHal, so it is unit-testable in
//  Node. The MakeCode glue (team_main.ts) implements the HAL.
//
//  Design (see protocol/PROTOCOL.md):
//   * The device measures the time of its own first key press relative to the
//     question start announced in beacons, so delivery delay never affects
//     fairness.
//   * The device keeps broadcasting its STATE (idempotent) until the base
//     acknowledges it in a beacon bitmask. No per-device connection exists.
//   * First press locks the answer; later presses are ignored.
// =============================================================================

// Display modes requested from the glue.
const QZ_D_UNASSIGNED = 0;
const QZ_D_IDLE = 1;      // a = slot
const QZ_D_WAIT = 2;      // a = LEDs lit for the countdown bar (0..25)
const QZ_D_LOCKED = 3;    // a = answer 1..5, b = 1 if acknowledged
const QZ_D_CLOSED = 4;    // a = answer 1..5 or 0
const QZ_D_RESULT = 5;    // a = 1 correct, 2 wrong, 3 no answer
const QZ_D_NOLINK = 6;
const QZ_D_IDENT = 7;
const QZ_D_LOCAL = 8;      // local test mode: a = letter 1..5 to show, 0 = none (blinking "!")

// Sounds requested from the glue (played by a background fiber).
const QZ_S_LOCK = 1;
const QZ_S_ACK = 2;
const QZ_S_INVALID = 3;
const QZ_S_CORRECT = 5;
const QZ_S_WRONG = 6;
const QZ_S_IDENT = 7;
const QZ_S_ASSIGNED = 8;

interface QzTeamHal {
    radioSend(bytes: number[]): void;
    sound(id: number): void;
    display(mode: number, a: number, b: number): void;
}

class QzTeam {
    hal: QzTeamHal;
    serial: number;
    slot = QZ_UNASSIGNED;

    // Last beacon seen
    bPhase = QZ_PH_IDLE;
    bQ = 0;
    bElapsed = 0;
    bLimit = 0;       // ms
    bAck = 0;
    bCorrect = 0;
    bWrong = 0;
    bFlags = 0;
    bAt = -1000000;   // local time the last beacon was handled
    lastBseq = -1;
    bmiss = 0;
    seenPhase = QZ_PH_IDLE;
    everBeacon = false;

    // Answer state (valid only while lockedQ == bQ)
    lockedQ = 0;
    ans = 0;
    ansElapsed = 0;
    acked = false;

    presses = 0;
    seq = 0;

    // TX scheduling
    nextTx = 0;
    txAttempts = 0;
    reportAt = -1;

    // Display / ident
    identUntil = -1;
    lastDMode = -1;
    lastDA = -1;
    lastDB = -1;
    resultKind = 3;

    // Key debounce
    lowSince: number[] = [];
    highSince: number[] = [];
    armed: boolean[] = [];
    nKeys: number;

    rngState = 0;

    constructor(hal: QzTeamHal, serial: number, nKeys: number, now: number) {
        this.hal = hal;
        this.serial = serial;
        this.nKeys = nKeys;
        for (let i = 0; i < nKeys; i++) {
            this.lowSince.push(-1);
            this.highSince.push(now);
            this.armed.push(false);   // a key already held at boot must be released first
        }
        // 16-bit LCG seeded from the device serial: different on every device.
        this.rngState = (serial ^ (serial >> 16)) & 0xFFFF;
        this.nextTx = now + this.rnd(0, 500);
    }

    // Inclusive pseudo-random integer in [lo, hi]. 16-bit LCG (full period);
    // the product stays below 2^31 so it is exact in int32 and in doubles.
    rnd(lo: number, hi: number): number {
        this.rngState = (this.rngState * 25173 + 13849) & 0xFFFF;
        const span = hi - lo + 1;
        return lo + (((this.rngState >> 3) * span) >> 13);
    }

    // ---- inputs -----------------------------------------------------------

    // Called for every received radio packet (already stripped of the MakeCode
    // header). Anything not ours is ignored.
    onPacket(bytes: number[], now: number) {
        const m = qzDecode(bytes);
        if (m == null) return;
        if (m.type == QZ_T_BEACON) this.onBeacon(m, now);
        else if (m.type == QZ_T_ASSIGN && m.target == this.serial) this.onAssign(m, now);
        else if (m.type == QZ_T_IDENT && m.target == this.serial) this.onIdent(m, now);
    }

    onAssign(m: QzMsg, now: number) {
        const changed = m.arg != this.slot;
        this.slot = m.arg;
        if (changed) {
            this.hal.sound(QZ_S_ASSIGNED);
            this.identUntil = now + 2500;
        }
        this.reportAt = now + this.rnd(0, 100);
    }

    onIdent(m: QzMsg, now: number) {
        this.identUntil = now + 3000;
        this.hal.sound(QZ_S_IDENT);
        this.reportAt = now + this.rnd(0, 100);
    }

    onBeacon(m: QzMsg, now: number) {
        // Count missed beacons (downlink loss) from the beacon sequence number.
        if (this.lastBseq >= 0) {
            const gap = (m.bseq - this.lastBseq - 1) & 255;
            if (gap > 0 && gap < 128 && this.bmiss < 255) this.bmiss = Math.min(255, this.bmiss + gap);
        }
        this.lastBseq = m.bseq;

        const prevPhase = this.bPhase;
        const prevQ = this.bQ;
        const first = !this.everBeacon;
        this.everBeacon = true;
        this.bPhase = m.phase;
        this.bQ = m.q;
        this.bElapsed = m.elapsed;
        this.bLimit = m.limit * 100;
        this.bAck = m.ack;
        this.bCorrect = m.correct;
        this.bWrong = m.wrong;
        this.bFlags = m.flags;
        this.bAt = now;

        // A new question number invalidates any answer held for an older one
        // (also protects against the 8-bit question counter wrapping around).
        if (m.q != prevQ && this.lockedQ != m.q) {
            this.lockedQ = 0;
            this.ans = 0;
            this.acked = false;
        }

        const phaseChanged = (m.phase != prevPhase) || (m.q != prevQ) || first;
        if (phaseChanged) {
            // Report the final state soon after any phase change (jittered so
            // 15 devices do not answer in the same millisecond).
            if (m.phase != QZ_PH_OPEN) this.reportAt = now + this.rnd(0, 250);
            if (m.phase == QZ_PH_REVEAL) this.onReveal();
        }
        this.seenPhase = m.phase;

        // Acknowledgement for our locked answer?
        if (this.slot != QZ_UNASSIGNED && this.lockedQ == this.bQ && this.lockedQ != 0 && !this.acked) {
            if (((this.bAck >> this.slot) & 1) == 1) {
                this.acked = true;
                this.hal.sound(QZ_S_ACK);
            }
        }

        // Stress-test mode: answer automatically on the first OPEN beacon.
        if (m.phase == QZ_PH_OPEN && (m.flags & QZ_BF_TEST) != 0 && this.slot != QZ_UNASSIGNED
            && !this.isLocked()) {
            const n = this.nAnswers();
            this.lockAnswer((this.slot % n) + 1, now, now);
        }
    }

    onReveal() {
        if (this.slot == QZ_UNASSIGNED) return;
        const bit = (1 << this.slot);
        if ((this.bCorrect & bit) != 0) {
            this.resultKind = 1; this.hal.sound(QZ_S_CORRECT);
        } else if ((this.bWrong & bit) != 0) {
            this.resultKind = 2; this.hal.sound(QZ_S_WRONG);
        } else {
            this.resultKind = 3;
        }
    }

    nAnswers(): number {
        const n = (this.bFlags >> QZ_BF_NANS_SHIFT) & 7;
        if (n < 3) return 3;
        if (n > 5) return 5;
        return n;
    }

    isLocked(): boolean {
        return this.lockedQ != 0 && this.lockedQ == this.bQ;
    }

    // Raw key states (true = pressed). Call every ~2 ms.
    onKeys(down: boolean[], now: number) {
        let winner = 0;
        let winnerT = 0;
        for (let k = 0; k < this.nKeys; k++) {
            if (down[k]) {
                this.highSince[k] = -1;
                if (this.lowSince[k] < 0) this.lowSince[k] = now;
                if (this.armed[k] && now - this.lowSince[k] >= QZ_DEBOUNCE_MS) {
                    this.armed[k] = false;
                    if (winner == 0) { winner = k + 1; winnerT = this.lowSince[k]; }   // same-tick tie: lowest index wins
                }
            } else {
                this.lowSince[k] = -1;
                if (this.highSince[k] < 0) this.highSince[k] = now;
                if (!this.armed[k] && now - this.highSince[k] >= QZ_DEBOUNCE_MS) this.armed[k] = true;
            }
        }
        if (winner > 0) this.onPress(winner, now, winnerT);
    }

    // tPress = local time the key went (and stayed) down, i.e. before the debounce delay.
    onPress(k: number, now: number, tPress: number) {
        this.presses = (this.presses + 1) & 0xFFFF;
        if (this.slot == QZ_UNASSIGNED) return;
        if (this.bPhase != QZ_PH_OPEN) return;
        if (now - this.bAt > QZ_STALE_MS) return;         // do not trust an old beacon
        if (this.isLocked()) return;                       // first press locks
        if (k > this.nAnswers()) { this.hal.sound(QZ_S_INVALID); return; }
        // Time is up on this device's own clock: do not pretend the answer counted.
        if (this.bLimit > 0 && this.bElapsed + (tPress - this.bAt) > this.bLimit) { this.hal.sound(QZ_S_INVALID); return; }
        this.lockAnswer(k, now, tPress);
    }

    lockAnswer(k: number, now: number, tPress: number) {
        let el = this.bElapsed + (tPress - this.bAt);
        if (el < 0) el = 0;
        if (el > 65535) el = 65535;
        this.ans = k;
        this.ansElapsed = el;
        this.lockedQ = this.bQ;
        this.acked = false;
        this.txAttempts = 0;
        this.hal.sound(QZ_S_LOCK);
        this.sendState(now);            // first transmission right away
    }

    // ---- periodic ---------------------------------------------------------

    tick(now: number) {
        if (this.reportAt >= 0 && now >= this.reportAt) {
            this.reportAt = -1;
            this.sendState(now);
        } else if (now >= this.nextTx) {
            this.sendState(now);
        }
        this.updateDisplay(now);
    }

    sendState(now: number) {
        const m = new QzMsg();
        m.slot = this.slot;
        m.seq = this.seq;
        this.seq = (this.seq + 1) & 255;
        m.q = this.bQ;
        const locked = this.isLocked();
        m.ans = locked ? this.ans : 0;
        m.elapsed = locked ? this.ansElapsed : 0;
        let f = 0;
        if (locked) f |= QZ_SF_LOCKED;
        if (locked && this.acked) f |= QZ_SF_ACKED;
        f |= (this.seenPhase & 7) << QZ_SF_PHASE_SHIFT;
        if ((this.bFlags & QZ_BF_TEST) != 0) f |= QZ_SF_TEST;
        m.flags = f;
        m.fw = QZ_FW;
        m.presses = this.presses;
        m.bmiss = this.bmiss;
        this.hal.radioSend(qzEncState(m));

        // Schedule the next transmission.
        let interval = 0;
        if (this.slot == QZ_UNASSIGNED) {
            interval = QZ_UNASSIGNED_HB_MS + this.rnd(0, 400);
        } else if (locked && !this.acked) {
            interval = this.txAttempts < 6 ? 50 + this.rnd(0, 100) : 150 + this.rnd(0, 200);
            this.txAttempts++;
        } else {
            interval = QZ_HB_MS + this.rnd(0, 300);
        }
        this.nextTx = now + interval;
    }

    updateDisplay(now: number) {
        let mode = 0;
        let a = 0;
        let b = 0;
        if (this.identUntil >= 0 && now < this.identUntil) {
            mode = QZ_D_IDENT; a = this.slot == QZ_UNASSIGNED ? 0 : this.slot + 1;
        } else if (this.slot == QZ_UNASSIGNED) {
            mode = QZ_D_UNASSIGNED;
        } else if (!this.everBeacon || now - this.bAt > QZ_NOLINK_MS || this.bPhase == QZ_PH_OFFLINE) {
            mode = QZ_D_NOLINK;
        } else if (this.bPhase == QZ_PH_OPEN) {
            if (this.isLocked()) {
                mode = QZ_D_LOCKED; a = this.ans; b = this.acked ? 1 : 0;
            } else {
                mode = QZ_D_WAIT;
                const limit = this.bLimit > 0 ? this.bLimit : 1;
                let remaining = limit - (this.bElapsed + (now - this.bAt));
                if (remaining < 0) remaining = 0;
                a = Math.min(25, Math.ceil((remaining * 25) / limit));
            }
        } else if (this.bPhase == QZ_PH_CLOSED) {
            mode = QZ_D_CLOSED; a = this.isLocked() ? this.ans : 0;
        } else if (this.bPhase == QZ_PH_REVEAL) {
            mode = QZ_D_RESULT; a = this.resultKind;
        } else {
            mode = QZ_D_IDLE; a = this.slot + 1;
        }
        if (mode != this.lastDMode || a != this.lastDA || b != this.lastDB) {
            this.lastDMode = mode; this.lastDA = a; this.lastDB = b;
            this.hal.display(mode, a, b);
        }
    }
}

// ===== qz_display.ts =====
// =============================================================================
//  DISPLAY FRAMES - pure functions (no hardware, no blocking, no shared state).
//  qzFrame() maps (display mode, a, b, ms since that state began) to the 5x5 picture that
//  must be on the LEDs at that moment. The hardware glue (team_main.ts) only draws the
//  result, so what the team sees is always a function of the CURRENT state: a late or
//  repeated state change can never leave a stale picture behind.
// =============================================================================

// ---- LED bitmaps (5x5, '#' = lit) ------------------------------------------
const QZ_LETTERS: string[][] = [
    [".###.", "#...#", "#####", "#...#", "#...#"],   // A
    ["####.", "#...#", "####.", "#...#", "####."],   // B
    [".####", "#....", "#....", "#....", ".####"],   // C
    ["####.", "#...#", "#...#", "#...#", "####."],   // D
    ["#####", "#....", "####.", "#....", "#####"]    // E
];
const QZ_DIGITS: string[][] = [
    ["###", "#.#", "#.#", "#.#", "###"],
    [".#.", "##.", ".#.", ".#.", "###"],
    ["###", "..#", "###", "#..", "###"],
    ["###", "..#", "###", "..#", "###"],
    ["#.#", "#.#", "###", "..#", "..#"],
    ["###", "#..", "###", "..#", "###"],
    ["###", "#..", "###", "#.#", "###"],
    ["###", "..#", "..#", "..#", "..#"],
    ["###", "#.#", "###", "#.#", "###"],
    ["###", "#.#", "###", "..#", "###"]
];
const QZ_ICON_CHECK = [".....", 
                       "....#", 
                       "...#.", 
                       "#.#..", 
                       ".#..."];

const QZ_ICON_CROSS = ["#...#", 
                       ".#.#.", 
                       "..#..", 
                       ".#.#.", 
                       "#...#"];

const QZ_ICON_DASH = [".....", 
                      ".....", 
                      ".###.", 
                      ".....", 
                      "....."];

const QZ_ICON_QUESTION = [".###.", 
                          "#...#", 
                          "..##.", 
                          ".....", 
                          "..#.."];

const QZ_ICON_NOLINK = ["#...#", 
                        ".....", 
                        "..#..", 
                        ".....", 
                        "#...#"];

const QZ_BLINK_PERIOD_MS = 350;      // locked but not yet confirmed by the base: letter blinks
const QZ_BLINK_ON_MS = 250;
const QZ_IDENT_STEP_MS = 120;        // identify: 3 flashes of 2 steps (dark, full), then the team number
const QZ_IDENT_STEPS = 6;

// Local test mode: a blinking "!" in the right-hand column (same shape as on the base station).
const QZ_ICON_BANG = ["###.#", 
                      ".#..#", 
                      ".#..#", 
                      ".#...", 
                      ".#..#"];
const QZ_ICON_BANG_BLANK = ["###..", 
                            ".#...", 
                            ".#...", 
                            ".#...", 
                            ".#..."];


const QZ_LOCAL_BLINK_MS = 700;       // full period of the "!" blink
const QZ_LOCAL_HOLD_MS = 400;        // a pressed letter stays visible this long after the key is released

const QZ_BLANK = [".....", 
                  ".....", 
                  ".....", 
                  ".....", 
                  "....."];
const QZ_FULL = ["#####", 
                 "#####", 
                 "#####", 
                 "#####", 
                 "#####"];

function qzNumberFrame(n: number): string[] {
    // 1..9: one 3x5 digit centred. 10..99: a bar for the tens "1" plus a 3x5 unit digit.
    const rows: string[] = [];
    const u = QZ_DIGITS[n % 10];
    for (let y = 0; y < 5; y++) {
        if (n < 10) rows.push("." + u[y] + ".");
        else rows.push("#." + u[y]);
    }
    return rows;
}

function qzBarFrame(lit: number): string[] {
    const rows: string[] = [];
    for (let y = 0; y < 5; y++) {
        let r = "";
        for (let x = 0; x < 5; x++) r += (y * 5 + x < lit) ? "#" : ".";
        rows.push(r);
    }
    return rows;
}

function qzFrame(mode: number, a: number, b: number, t: number): string[] {
    if (mode == QZ_D_UNASSIGNED) return QZ_ICON_QUESTION;
    if (mode == QZ_D_IDLE) return qzNumberFrame(a);
    if (mode == QZ_D_WAIT) return qzBarFrame(a);
    if (mode == QZ_D_LOCKED || mode == QZ_D_CLOSED) {
        if (a < 1 || a > 5) return QZ_ICON_DASH;
        if (mode == QZ_D_LOCKED && b == 0) return (t % QZ_BLINK_PERIOD_MS) < QZ_BLINK_ON_MS ? QZ_LETTERS[a - 1] : QZ_BLANK;
        return QZ_LETTERS[a - 1];
    }
    if (mode == QZ_D_RESULT) return a == 1 ? QZ_ICON_CHECK : (a == 2 ? QZ_ICON_CROSS : QZ_ICON_DASH);
    if (mode == QZ_D_NOLINK) return QZ_ICON_NOLINK;
    if (mode == QZ_D_LOCAL) {
        if (a >= 1 && a <= 5) return QZ_LETTERS[a - 1];
        return (t % QZ_LOCAL_BLINK_MS) < Math.idiv(QZ_LOCAL_BLINK_MS, 2) ? QZ_ICON_BANG : QZ_ICON_BANG_BLANK;
    }
    if (mode == QZ_D_IDENT) {
        const step = Math.idiv(t, QZ_IDENT_STEP_MS);
        if (step < QZ_IDENT_STEPS) return (step % 2) == 0 ? QZ_BLANK : QZ_FULL;
        return a > 0 ? qzNumberFrame(a) : QZ_BLANK;
    }
    return QZ_BLANK;
}


// ---- local test mode: which letter to show for the keys currently pressed ----------------------
// Pure state machine (the glue only feeds it the key states and draws the result). In this mode the
// device sends nothing on the radio and ignores everything it receives.
class QzLocalTest {
    show = 0;                 // letter 1..5 to display, 0 = none
    until = 0;                // the letter stays on screen until this time
    prev: boolean[] = [];

    constructor() { }

    // Returns true when a key has just been pressed (the glue plays a local beep).
    onKeys(down: boolean[], now: number): boolean {
        let fresh = false;
        let any = false;
        for (let i = 0; i < down.length; i++) {
            const was = i < this.prev.length ? this.prev[i] : false;
            if (down[i]) {
                any = true;
                if (!was) { this.show = i + 1; fresh = true; }
            }
        }
        this.prev = [];
        for (let i = 0; i < down.length; i++) this.prev.push(down[i]);
        if (any) this.until = now + QZ_LOCAL_HOLD_MS;
        else if (now >= this.until) this.show = 0;
        return fresh;
    }
}

// ===== team_main.ts =====
// =============================================================================
//  TEAM DEVICE - MakeCode glue (micro:bit on an edu:bit, answer keys on pins).
//  All game logic lives in qz_team.ts; this file only talks to the hardware.
// =============================================================================

// ---- EDIT ME: which input drives each answer (A, B, C, D, E) ---------------

const QZ_BTN_A = 1000;
const QZ_BTN_B = 1001;
const QZ_KEY_SOURCES: number[] = [QZ_BTN_A, QZ_BTN_B, DigitalPin.P8, DigitalPin.P12]; 
const QZ_VOLUME = 200;          // 0..255

// ---- hardware access --------------------------------------------------------
let qzSoundQueue: number[] = [];
// Current display state, written by the HAL and read by the display fiber (cooperative fibers: no tearing).
let qzDMode = QZ_D_UNASSIGNED;
let qzDA = 0;
let qzDB = 0;
let qzDSince = 0;               // control.millis() when the state last changed (drives blinking and flashes)

// Local test mode (touch logo, micro:bit V2): nothing is sent or received on the radio, and a pressed
// key just shows its letter. Touch the logo again to leave it.
let qzLocal = false;
let qzLocalSince = 0;
let qzLogoAt = -1000;
let qzWaitRelease = false;      // after leaving test mode, keys still held are not fed to the game logic
const qzLocalTest = new QzLocalTest();

class TeamHal implements QzTeamHal {
    radioSend(bytes: number[]): void {
        const b = control.createBuffer(bytes.length);
        for (let i = 0; i < bytes.length; i++) b[i] = bytes[i];
        radio.sendBuffer(b);
    }
    sound(id: number): void {
        if (qzSoundQueue.length < 6) qzSoundQueue.push(id);
    }
    display(mode: number, a: number, b: number): void {
        if (mode != qzDMode || a != qzDA || b != qzDB) {
            qzDMode = mode; qzDA = a; qzDB = b; qzDSince = control.millis();
        }
    }
}

function qzBufToArray(b: Buffer): number[] {
    const out: number[] = [];
    for (let i = 0; i < b.length; i++) out.push(b[i]);
    return out;
}

function qzReadKey(src: number): boolean {
    if (src == QZ_BTN_A) return input.buttonIsPressed(Button.A);
    if (src == QZ_BTN_B) return input.buttonIsPressed(Button.B);
    return pins.digitalReadPin(src) == 0;      // active low, pull-up enabled
}

function qzDraw(rows: string[]) {
    for (let y = 0; y < 5; y++) {
        for (let x = 0; x < 5; x++) {
            if (rows.length > y && rows[y].charAt(x) == "#") led.plot(x, y); else led.unplot(x, y);
        }
    }
}

let qzLastFrame = "";

function qzPlay(id: number) {
    if (id == QZ_S_LOCK) { music.playTone(880, 60); }
    else if (id == QZ_S_ACK) { music.playTone(660, 40); music.playTone(990, 60); }
    else if (id == QZ_S_INVALID) { music.playTone(220, 80); }
    else if (id == QZ_S_CORRECT) { music.playTone(523, 120); music.playTone(659, 120); music.playTone(784, 240); }
    else if (id == QZ_S_WRONG) { music.playTone(330, 150); music.playTone(196, 350); }
    else if (id == QZ_S_IDENT) { for (let i = 0; i < 3; i++) { music.playTone(1000, 100); basic.pause(100); } }
    else if (id == QZ_S_ASSIGNED) { music.playTone(784, 80); music.playTone(1047, 120); }
}

// ---- start-up ---------------------------------------------------------------
radio.setGroup(QZ_GROUP);
radio.setFrequencyBand(QZ_BAND);
radio.setTransmitPower(QZ_TX_POWER);
radio.setTransmitSerialNumber(true);
music.setVolume(QZ_VOLUME);
// The audio engine drives the edge-connector audio pin (P0 by default) continuously once it has started,
// and the edu:bit's P0 current indicator then blinks forever. Keep that pin released and connect it only
// while a sound is playing (the on-board speaker of the V2 is not affected).
pins.setAudioPinEnabled(false);
for (let i = 0; i < QZ_KEY_SOURCES.length; i++) {
    if (QZ_KEY_SOURCES[i] < 1000) pins.setPull(QZ_KEY_SOURCES[i], PinPullMode.PullUp);
}

const qzTeam = new QzTeam(new TeamHal(), control.deviceSerialNumber(), QZ_KEY_SOURCES.length, control.millis());

radio.onReceivedBuffer(function (b: Buffer) {
    if (qzLocal) return;                 // test mode: incoming radio is ignored
    qzTeam.onPacket(qzBufToArray(b), control.millis());
});

// Main loop: poll keys every 2 ms (debounce, press timing and TX scheduling live in QzTeam).
control.inBackground(function () {
    const down: boolean[] = [];
    for (let i = 0; i < QZ_KEY_SOURCES.length; i++) down.push(false);
    while (true) {
        const now = control.millis();
        for (let i = 0; i < QZ_KEY_SOURCES.length; i++) down[i] = qzReadKey(QZ_KEY_SOURCES[i]);
        if (qzLocal) {
            // test mode: no game logic, hence no radio transmission at all
            if (qzLocalTest.onKeys(down, now) && qzSoundQueue.length < 6) qzSoundQueue.push(QZ_S_LOCK);
        } else {
            let anyDown = false;
            for (let i = 0; i < down.length; i++) if (down[i]) anyDown = true;
            if (!anyDown) qzWaitRelease = false;
            if (!qzWaitRelease) {
                qzTeam.onKeys(down, now);
                qzTeam.tick(now);
            }
        }
        basic.pause(2);
    }
});

// Display and sound run in their own fibers so they can block without delaying key scanning.
control.inBackground(function () {
    while (true) {
        // Never blocks and never keeps a copy of the state: draw whatever the CURRENT state looks like now.
        const t = control.millis();
        const frame = qzLocal ? qzFrame(QZ_D_LOCAL, qzLocalTest.show, 0, t - qzLocalSince)
                              : qzFrame(qzDMode, qzDA, qzDB, t - qzDSince);
        const key = frame.join("");
        if (key != qzLastFrame) { qzLastFrame = key; qzDraw(frame); }
        basic.pause(20);
    }
});
control.inBackground(function () {
    while (true) {
        if (qzSoundQueue.length > 0) {
            pins.setAudioPinEnabled(true);
            while (qzSoundQueue.length > 0) qzPlay(qzSoundQueue.shift());
            pins.setAudioPinEnabled(false);
        } else basic.pause(10);
    }
});

// Touch logo toggles local test mode (the logo exists on micro:bit V2 only).
input.onLogoEvent(TouchButtonEvent.Pressed, function () {
    const now = control.millis();
    if (now - qzLogoAt < 400) return;    // a touch can report twice
    qzLogoAt = now;
    qzLocal = !qzLocal;
    qzLocalSince = now;
    qzLocalTest.show = 0;
    qzLocalTest.until = 0;
    qzLocalTest.prev = [];
    qzWaitRelease = !qzLocal;
    if (qzSoundQueue.length < 6) qzSoundQueue.push(qzLocal ? QZ_S_ASSIGNED : QZ_S_ACK);
});
